object Ctx {
  private val tl = new InheritableThreadLocal[RequestContext] {
    override def initialValue(): RequestContext = RequestContext()
  }
  def current: RequestContext = tl.get
  def withContext[A](ctx: RequestContext)(body: => A): A = {
    val old = tl.get; tl.set(ctx)
    try body finally tl.set(old)      // restore on every path
  }
}

